def strategy(history, rng):
    n = len(history)
    if n <= 4:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for x in opp if x == 'D')

    if opp_def == n and n >= 5:
        return 'D'

    forg = 0
    ret = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'C':
                forg += 1
            else:
                ret += 1

    recent = opp[-10:]
    recent_c = sum(1 for x in recent if x == 'C')
    recent_rate = recent_c / len(recent) if recent else 1.0

    if opp[-1] == 'D':
        if opp_def <= max(1, n // 10):
            return 'C'
        if forg > ret:
            return 'D'
        return 'C'

    if recent_rate < 0.6:
        return 'C'

    K = 8 + 2 * (ret - forg)
    if K < 1:
        K = 1
    if K > 20:
        K = 20

    last_def = -1
    for i in range(n - 1, -1, -1):
        if my[i] == 'D':
            last_def = i
            break

    if last_def == -1:
        return 'D'

    if n - last_def >= K:
        return 'D'

    return 'C'
